import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import './Navigation.css';
import logoImage from '../assets/images/logo_neto.png';
import TextEditor from './TextEditor';

const Navigation: React.FC = () => {
  const location = useLocation();
  const [isTextEditorOpen, setIsTextEditorOpen] = useState(false);

  const navItems = [
    { path: '/', label: 'Inicio' },
    { path: '/bio', label: 'BIO' },
    { path: '/out-the-music', label: 'Out the music' },
    { path: '/contacto', label: 'Contact ▼' }
  ];

  const handleTextSave = (content: any) => {
    console.log('Texto guardado:', content);
    // Aquí puedes implementar la lógica para guardar el texto
  };

  return (
    <>
      <nav className="navigation">
        <div className="nav-container">
          <div className="logo-section">
            <div className="logo-icon">
              <img src={logoImage} alt="Neto Logo" className="logo-image" />
            </div>
            <div className="logo-text">
              <h1 className="logo-name">Adolfo Gutiérrez Arenas</h1>
            </div>
          </div>
          <ul className="nav-menu">
            {navItems.map((item) => (
              <li key={item.path} className="nav-item">
                <Link 
                  to={item.path} 
                  className={`nav-link ${location.pathname === item.path ? 'active' : ''}`}
                >
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>
          <button 
            className="text-editor-btn"
            onClick={() => setIsTextEditorOpen(true)}
            title="Editor de Textos"
          >
            ✏️ Editar Textos
          </button>
        </div>
      </nav>

      <TextEditor
        isOpen={isTextEditorOpen}
        onClose={() => setIsTextEditorOpen(false)}
        onSave={handleTextSave}
      />
    </>
  );
};

export default Navigation;
